insert into public.sources (id, publisher, title, url, class, licence, method, coverage, limitations, last_checked) values ('census2001-hhaa-keyresults-rajasthan', 'Office of the Registrar General & Census Commissioner, India', 'Census of India 2001 - Where and How People Live? Data on Housing Stock, Household Amenities and Assets - Rajasthan Key Results (presentation PDF)', 'https://censusindia.gov.in/nada/index.php/catalog/27651/download/30804/Data%20on%20Housing%20StockHousehold%20Amenities%20and%20Assets%20Presentation%20Rajasthan.pdf', 'A', 'Government of India publication; reuse with attribution to the source', 'State key-results slides from the 2001 Houselisting and Housing Census; State column read from pdftotext -raw text. Every recorded value was cross-checked against State-level counts in Census 2001 tables H-08, H-09, H-11 and H-13 (within 0.05 points after rounding); values that failed were left out.', 'Rajasthan (and India column), Census 2001, total (rural+urban) households.', 'Slides print one decimal. Latrine is printed only as ''No latrine'' within the house, so latrine-within-premises is not recorded from this deck. The India ''Kerosene'' column on the cooking-fuel slide differs between decks (6.5 or 9.8); LPG values used here were each checked against the H-11 table.', '2026-10-16') on conflict (id) do update set publisher = excluded.publisher, title = excluded.title, url = excluded.url, class = excluded.class, licence = excluded.licence, method = excluded.method, coverage = excluded.coverage, limitations = excluded.limitations, last_checked = excluded.last_checked;
insert into public.sources (id, publisher, title, url, class, licence, method, coverage, limitations, last_checked) values ('census2001-hhaa-keyresults-uttar-pradesh', 'Office of the Registrar General & Census Commissioner, India', 'Census of India 2001 - Where and How People Live? Data on Housing Stock, Household Amenities and Assets - Uttar Pradesh Key Results (presentation PDF)', 'https://censusindia.gov.in/nada/index.php/catalog/27652/download/30806/Data%20on%20Housing%20StockHousehold%20Amenities%20and%20Assets%20Presentation%20Uttar%20Pradesh.pdf', 'A', 'Government of India publication; reuse with attribution to the source', 'State key-results slides from the 2001 Houselisting and Housing Census; State column read from pdftotext -raw text. Every recorded value was cross-checked against State-level counts in Census 2001 tables H-08, H-09, H-11 and H-13 (within 0.05 points after rounding); values that failed were left out.', 'Uttar Pradesh (and India column), Census 2001, total (rural+urban) households.', 'Slides print one decimal. Latrine is printed only as ''No latrine'' within the house, so latrine-within-premises is not recorded from this deck. The India ''Kerosene'' column on the cooking-fuel slide differs between decks (6.5 or 9.8); LPG values used here were each checked against the H-11 table. The LPG figure on this deck''s cooking-fuel slide does not match the State H-11 table (looks like a column mix-up), so LPG is not recorded.', '2026-10-16') on conflict (id) do update set publisher = excluded.publisher, title = excluded.title, url = excluded.url, class = excluded.class, licence = excluded.licence, method = excluded.method, coverage = excluded.coverage, limitations = excluded.limitations, last_checked = excluded.last_checked;
