insert into public.sources (id, publisher, title, url, class, licence, method, coverage, limitations, last_checked) values ('ub-ndg-2011-12-d21', 'Ministry of Finance, Union Budget (Expenditure Budget: Notes on Demands for Grants)', 'Notes on Demands for Grants 2011-12: Demand No. 21, Defence Pensions (Ministry of Defence)', 'https://www.indiabudget.gov.in/budget2011-2012/ub2011-12/eb/sbe21.pdf', 'A', 'Government of India budget document (indiabudget.gov.in); public record, cited with attribution.', 'Budget allocation of the demand, net of recoveries (and of receipts, where the document shows them). Each document gives Actuals for two years earlier, Budget and Revised Estimates for the previous year and the Budget Estimate for the year.', 'Act2009-2010, Bud2010-2011, Rev2010-2011, Bud2011-2012: [34999.45, 25000.0, 34000.0, 34000.0] (Rs crore)', 'Covers only this demand. Defence spending also sits in the Ministry of Defence (Civil) demand, and SIPRI adds paramilitary forces. Demands were reorganised in the 2016-17 documents.', '2026-10-16') on conflict (id) do update set publisher = excluded.publisher, title = excluded.title, url = excluded.url, class = excluded.class, licence = excluded.licence, method = excluded.method, coverage = excluded.coverage, limitations = excluded.limitations, last_checked = excluded.last_checked;
