insert into public.sources (id, publisher, title, url, class, licence, method, coverage, limitations, last_checked) values ('moe-udiseplus-2020-21', 'Ministry of Education, Department of School Education & Literacy (UDISE+)', 'Report on UDISE+ 2020-21: Table 1.1: Number of schools by level of school education, 2020-21; Table 5.1: Gross Enrolment Ratio (GER) by Gender and Level of School Education, 2020-21; Table 2.11: Pupil Teacher Ratio (PTR) by level of school education, 2020-21', 'https://dashboard.udiseplus.gov.in/report2026/static/media/UDISE+2020_21_Booklet.2cfe0df9249cc690d12d.pdf', 'A', 'Government of India publication on the UDISE+ dashboard; no explicit open licence stated in the file; reuse with attribution to Ministry of Education, UDISE+', 'Downloaded from the UDISE+ dashboard report bundle (dashboard.udiseplus.gov.in, Reports). Text extracted with pdftotext -table. Values copied exactly as printed: schools = Total column of the schools-by-level table (all managements); GER = Secondary (9-10) Total, All Social Groups; PTR = Secondary (9-10). Checks: school Total equals the sum of the four levels and GER total lies between boys and girls in every row.', 'India plus 36 States/UTs, academic year 2020-21', 'GER denominators are population projections based on the MoHFW Expert Group report (2020), as stated in the report; GER can exceed 100 or move with projection revisions. Secondary PTR printed as whole numbers in every edition except 2019-20 (one decimal).', '2026-10-16') on conflict (id) do update set publisher = excluded.publisher, title = excluded.title, url = excluded.url, class = excluded.class, licence = excluded.licence, method = excluded.method, coverage = excluded.coverage, limitations = excluded.limitations, last_checked = excluded.last_checked;
insert into public.sources (id, publisher, title, url, class, licence, method, coverage, limitations, last_checked) values ('moe-udiseplus-2021-22', 'Ministry of Education, Department of School Education & Literacy (UDISE+)', 'Report on UDISE+ 2021-22: Table 3.1: Number of schools by level of school education, 2021-22; Table 6.1: Gross Enrolment Ratio (GER) by Gender and Level of School Education, 2021-22; Table 4.11: Pupil Teacher Ratio (PTR) by level of school education, 2021-22', 'https://dashboard.udiseplus.gov.in/report2026/static/media/UDISE+2021_22_Booklet.f55c1a60ed700e6c7892.pdf', 'A', 'Government of India publication on the UDISE+ dashboard; no explicit open licence stated in the file; reuse with attribution to Ministry of Education, UDISE+', 'Downloaded from the UDISE+ dashboard report bundle (dashboard.udiseplus.gov.in, Reports). Text extracted with pdftotext -table. Values copied exactly as printed: schools = Total column of the schools-by-level table (all managements); GER = Secondary (9-10) Total, All Social Groups; PTR = Secondary (9-10). Checks: school Total equals the sum of the four levels and GER total lies between boys and girls in every row.', 'India plus 36 States/UTs, academic year 2021-22', 'GER denominators are population projections based on the MoHFW Expert Group report (2020), as stated in the report; GER can exceed 100 or move with projection revisions. Secondary PTR printed as whole numbers in every edition except 2019-20 (one decimal).', '2026-10-16') on conflict (id) do update set publisher = excluded.publisher, title = excluded.title, url = excluded.url, class = excluded.class, licence = excluded.licence, method = excluded.method, coverage = excluded.coverage, limitations = excluded.limitations, last_checked = excluded.last_checked;
insert into public.sources (id, publisher, title, url, class, licence, method, coverage, limitations, last_checked) values ('moe-udiseplus-2022-23', 'Ministry of Education, Department of School Education & Literacy (UDISE+)', 'Report on UDISE+ 2022-23 (existing-structure booklet): Table 3.1: Number of schools by level of school education, 2022-23; Table 6.1: Gross Enrolment Ratio (GER) by Gender and Level of School Education, 2022-23: All Social Groups; Table 4.12: Pupil Teacher Ratio (PTR) by level of school education, 2022-23', 'https://dashboard.udiseplus.gov.in/report2026/static/media/UDISE+2022_23_Booklet_existing.d209e7c7516d77939da9.pdf', 'A', 'Government of India publication on the UDISE+ dashboard; no explicit open licence stated in the file; reuse with attribution to Ministry of Education, UDISE+', 'Downloaded from the UDISE+ dashboard report bundle (dashboard.udiseplus.gov.in, Reports). Text extracted with pdftotext -table. Values copied exactly as printed: schools = Total column of the schools-by-level table (all managements); GER = Secondary (9-10) Total, All Social Groups; PTR = Secondary (9-10). Checks: school Total equals the sum of the four levels and GER total lies between boys and girls in every row.', 'India plus 36 States/UTs, academic year 2022-23', 'Report states that from 2022-23 data are collected student-wise (not school-consolidated) and population projections were moderated using SRS birth-rate trends, UIDAI Aadhaar saturation and neighbouring-state trends, so GER/PTR are not strictly comparable with 2021-22 and earlier (break flagged at 2022-23). The existing-structure edition is used (Secondary = classes IX-X); the separate NEP-structure edition groups Secondary as IX-XII. GER denominators are population projections based on the MoHFW Expert Group report (2020), as stated in the report; GER can exceed 100 or move with projection revisions. Secondary PTR printed as whole numbers in every edition except 2019-20 (one decimal).', '2026-10-16') on conflict (id) do update set publisher = excluded.publisher, title = excluded.title, url = excluded.url, class = excluded.class, licence = excluded.licence, method = excluded.method, coverage = excluded.coverage, limitations = excluded.limitations, last_checked = excluded.last_checked;
