insert into public.sources (id, publisher, title, url, class, licence, method, coverage, limitations, last_checked) values ('aishe-ger-timeseries-2011proj', 'Ministry of Education (Ministry of Human Resource Development before 2020), Department of Higher Education - All India Survey on Higher Education (AISHE)', 'Time series for GER based on 2011 Pop Projection (Gross Enrolment Ratio from AISHE based on Population Projection of 2011 Census), 2011-12 to 2021-22', 'https://cdnbbsr.s3waas.gov.in/s392049debbe566ca5782a3045cf300a3c/uploads/2025/06/202506041164303308.pdf', 'A', 'Government of India publication on aishe.gov.in; no explicit open licence stated in the PDF; reuse with attribution', 'One-page PDF listed on https://aishe.gov.in/aishe-final-report/ ; All-India GER (All, Person column) 2011-12 to 2021-22, re-computed by AISHE on Census-2011-based population projections. Copied as printed.', 'All-India only; 2011-12 to 2021-22; 11 values', 'No State/UT breakdown. Values for 2011-12 to 2019-20 differ from the GER printed in the original annual reports (which used 2001-census projections).', '2026-10-16') on conflict (id) do update set publisher = excluded.publisher, title = excluded.title, url = excluded.url, class = excluded.class, licence = excluded.licence, method = excluded.method, coverage = excluded.coverage, limitations = excluded.limitations, last_checked = excluded.last_checked;
